39	type BaseReconciler struct {
40		client.Client
41	}
42	
43	func (r *BaseReconciler) ReconcilePodObject(ctx context.Context, desired *corev1.Pod) error {
44		found := &corev1.Pod{}
45		err := r.Get(ctx, types.NamespacedName{Name: desired.Name, Namespace: desired.Namespace}, found)
46		if err != nil && apierrors.IsNotFound(err) {
47			klog.InfoS("Creating a new Pod", "Pod.Namespace", desired.Namespace, "Pod.Name", desired.Name)
48			return r.Create(ctx, desired)
49		} else if err != nil {
50			return err
51		}
52	
53		// Check if the images need to be updated.
54		// most Pod fields are mutable, so we just compare image here. We can extends to tolerations or other fields later.
55		updateNeeded := false
56		for i, container := range found.Spec.Containers {
57			if len(desired.Spec.Containers) > i {
58				if desired.Spec.Containers[i].Image != container.Image {
59					// update the image
60					found.Spec.Containers[i].Image = desired.Spec.Containers[i].Image
61					updateNeeded = true
62				}
63			}
64		}
65	
66		if updateNeeded {
67			klog.InfoS("Updating Pod", "Pod.Namespace", found.Namespace, "Pod.Name", found.Name)
68			return r.Update(ctx, found)
69		}
70	
71		return nil
72	}
73	
74	func (r *BaseReconciler) ReconcileDeploymentObject(ctx context.Context, desired *appsv1.Deployment) error {
75		found := &appsv1.Deployment{}
76		err := r.Get(ctx, types.NamespacedName{Name: desired.Name, Namespace: desired.Namespace}, found)
77		if err != nil && apierrors.IsNotFound(err) {
78			klog.InfoS("Creating Deployment", "Name", desired.Name)
79			return r.Create(ctx, desired)
80		} else if err != nil {
81			return err
82		} else if needsUpdateDeployment(desired, found) {
83			found.Spec = desired.Spec
84			klog.InfoS("Updating Deployment", "Name", desired.Name)
85			return r.Update(ctx, found)
86		}
87		return nil
88	}
89	
90	func (r *BaseReconciler) ReconcileServiceObject(ctx context.Context, service *corev1.Service) error {
91		found := &corev1.Service{}
92		err := r.Get(ctx, types.NamespacedName{Name: service.Name, Namespace: service.Namespace}, found)
93		if err != nil && apierrors.IsNotFound(err) {
94			klog.InfoS("Creating a new Service", "Service.Namespace", service.Namespace, "Service.Name", service.Name)
95			return r.Create(ctx, service)
96		} else if err != nil {
97			return err
98		}
99	
100		// Update the found object and write the result back if there are any changes
101		if needsUpdateService(service, found) {
102			found.Spec.Ports = service.Spec.Ports
103			found.Spec.Selector = service.Spec.Selector
104			found.Spec.Type = service.Spec.Type
105			klog.InfoS("Updating Service", "Service.Namespace", found.Namespace, "Service.Name", found.Name)
106			return r.Update(ctx, found)
107		}
108	
109		return nil
110	}
