112	func (r *BaseReconciler) ReconcileStatefulsetObject(ctx context.Context, sts *appsv1.StatefulSet) error {
113		found := &appsv1.StatefulSet{}
114		err := r.Get(ctx, types.NamespacedName{Name: sts.Name, Namespace: sts.Namespace}, found)
115		if err != nil && apierrors.IsNotFound(err) {
