123		if needsUpdateStatefulset(sts, found) {
124			found.Spec = sts.Spec
125			klog.InfoS("Updating Statefulset", "Sts.Namespace", found.Namespace, "Sts.Name", found.Name)
126			return r.Update(ctx, found)
127		}
