168	// needsUpdateService checks if the service spec of the new service differs from the existing one
169	func needsUpdateService(service, found *corev1.Service) bool {
170		// Compare relevant spec fields
171		return !reflect.DeepEqual(service.Spec.Ports, found.Spec.Ports) ||
172			!reflect.DeepEqual(service.Spec.Selector, found.Spec.Selector) ||
173			service.Spec.Type != found.Spec.Type
174	}
175	
176	// needsUpdateDeployment checks if the deployment spec of the new deployment differs from the existing one
177	// only image and replicas are considered at this moment.
178	func needsUpdateDeployment(deployment *appsv1.Deployment, found *appsv1.Deployment) bool {
179		imageChanged := false
180		for i, container := range found.Spec.Template.Spec.Containers {
181			if len(deployment.Spec.Template.Spec.Containers) > i {
182				if deployment.Spec.Template.Spec.Containers[i].Image != container.Image {
183					// update the image
184					found.Spec.Template.Spec.Containers[i].Image = deployment.Spec.Template.Spec.Containers[i].Image
185					imageChanged = true
186				}
187			}
188		}
189	
190		return !reflect.DeepEqual(deployment.Spec.Replicas, found.Spec.Replicas) || imageChanged
191	}
192	
193	// needsUpdateStatefulset checks if the StatefulSet spec of the new Statefulset differs from the existing one
194	// only image and replicas are considered at this moment.
195	func needsUpdateStatefulset(sts *appsv1.StatefulSet, found *appsv1.StatefulSet) bool {
196		imageChanged := false
197		for i, container := range found.Spec.Template.Spec.Containers {
198			if len(sts.Spec.Template.Spec.Containers) > i {
199				if sts.Spec.Template.Spec.Containers[i].Image != container.Image {
200					// update the image
201					found.Spec.Template.Spec.Containers[i].Image = sts.Spec.Template.Spec.Containers[i].Image
202					imageChanged = true
203				}
204			}
205		}
206	
207		return !reflect.DeepEqual(sts.Spec.Replicas, found.Spec.Replicas) || imageChanged
208	}
