212		ValidateObject(*orchestrationv1alpha1.KVCache) error
213		BuildMetadataPod(*orchestrationv1alpha1.KVCache) *corev1.Pod
214		BuildMetadataService(*orchestrationv1alpha1.KVCache) *corev1.Service
215		BuildWatcherPodServiceAccount(*orchestrationv1alpha1.KVCache) *corev1.ServiceAccount
216		BuildWatcherPodRole(*orchestrationv1alpha1.KVCache) *rbacv1.Role
217		BuildWatcherPodRoleBinding(*orchestrationv1alpha1.KVCache) *rbacv1.RoleBinding
218		BuildWatcherPod(*orchestrationv1alpha1.KVCache) *corev1.Pod
219		BuildCacheStatefulSet(*orchestrationv1alpha1.KVCache) *appsv1.StatefulSet
220		BuildService(*orchestrationv1alpha1.KVCache) *corev1.Service
221	}
