57	func (r *DistributedReconciler) Reconcile(ctx context.Context, kvCache *orchestrationv1alpha1.KVCache) (ctrl.Result, error) {
58		if err := r.Backend.ValidateObject(kvCache); err != nil {
59			return ctrl.Result{}, err
