100	func (r *DistributedReconciler) reconcileMetadataService(ctx context.Context, kvCache *orchestrationv1alpha1.KVCache) error {
101		if kvCache.Spec.Metadata != nil && kvCache.Spec.Metadata.Etcd == nil && kvCache.Spec.Metadata.Redis == nil {
102			return errors.New("either etcd or redis configuration is required")
103		}
104	
105		if kvCache.Spec.Metadata.Redis != nil {
106			return r.reconcileRedisService(ctx, kvCache)
107		}
108	
109		return nil
110	}
