112	func (r *DistributedReconciler) reconcileRedisService(ctx context.Context, kvCache *orchestrationv1alpha1.KVCache) error {
113		redisConfig := kvCache.Spec.Metadata.Redis
114	
115		// If an external connection is configured, skip in-cluster Redis deployment.
116		// The operator is providing their own managed Valkey/Redis-compatible endpoint.
117		if redisConfig.ExternalConnection != nil && redisConfig.ExternalConnection.Address != "" {
118			// Validate first — only clean up in-cluster resources once the external
119			// config is confirmed to be well-formed
120			if err := r.validateExternalConnection(ctx, kvCache); err != nil {
121				return err
122			}
123	
124			klog.Infof("Using external metadata connection at %s, skipping in-cluster Redis deployment", redisConfig.ExternalConnection.Address)
125	
126			// Only tear down in-cluster Redis once the external config is known-good.
127			// Returning the error on failure is intentional — the reconcile loop will
128			// retry until cleanup succeeds. Partial cleanup (e.g., Pod deleted but
129			// Service remains) is safe because the retry will finish the job.
130			if err := r.cleanupInClusterRedis(ctx, kvCache); err != nil {
131				return fmt.Errorf("cleaning up in-cluster Redis: %w", err)
132			}
133	
134			return nil
135		}
136	
137		// Fall back to in-cluster Redis deployment (existing behavior).
138		if redisConfig.Runtime == nil {
139			return errors.New("redis metadata config requires either externalConnection or runtime to be set")
140		}
141	
142		replicas := int(redisConfig.Runtime.Replicas)
143		if replicas != 1 {
144			klog.Warningf("replica %d > 1 is not supported at this moment, we will change to single replica", replicas)
145		}
146	
147		pod := r.Backend.BuildMetadataPod(kvCache)
148		if err := r.ReconcilePodObject(ctx, pod); err != nil {
149			return err
150		}
151	
152		// Create or update the metadata service for each pod
153		metadataService := r.Backend.BuildMetadataService(kvCache)
154		if err := r.ReconcileServiceObject(ctx, metadataService); err != nil {
155			return err
156		}
157	
158		return nil
159	}
