161	// validateExternalConnection validates the external connection configuration
162	// without reading secret values into memory.
163	func (r *DistributedReconciler) validateExternalConnection(ctx context.Context, kvCache *orchestrationv1alpha1.KVCache) error {
164		extConn := kvCache.Spec.Metadata.Redis.ExternalConnection
165	
166		// Validate address format (host:port)
167		if _, _, err := net.SplitHostPort(extConn.Address); err != nil {
168			return fmt.Errorf("external connection address %q must be in host:port format: %w", extConn.Address, err)
169		}
170	
171		// If a password secret reference is provided, verify the secret and key exist.
172		if extConn.PasswordSecretRef != "" {
173			if err := r.validateSecretExists(ctx, kvCache.Namespace, extConn.PasswordSecretRef); err != nil {
174				return fmt.Errorf("failed to resolve PasswordSecretRef %q: %w", extConn.PasswordSecretRef, err)
175			}
176		}
177	
178		return nil
179	}
