181	// validateSecretExists checks that a Kubernetes Secret and key exist without
182	// reading the secret value into memory. Use this for validation-only paths
183	// where the value will be injected via SecretKeyRef rather than resolved at runtime.
184	func (r *DistributedReconciler) validateSecretExists(ctx context.Context, namespace, secretRef string) error {
185		secretName, secretKey := parseSecretRef(secretRef)
186	
187		secret := &corev1.Secret{}
188		if err := r.Client.Get(ctx, types.NamespacedName{
189			Namespace: namespace,
190			Name:      secretName,
191		}, secret); err != nil {
192			return fmt.Errorf("failed to get secret %q in namespace %q: %w", secretName, namespace, err)
193		}
194	
195		if _, ok := secret.Data[secretKey]; !ok {
196			return fmt.Errorf("key %q not found in secret %q", secretKey, secretName)
197		}
198	
199		return nil
200	}
201	
202	// cleanupInClusterRedis deletes the in-cluster Redis Pod and Service that may
203	// have been previously created. This handles the migration path from in-cluster
204	// to external connection without leaving orphaned resources.
205	func (r *DistributedReconciler) cleanupInClusterRedis(ctx context.Context, kvCache *orchestrationv1alpha1.KVCache) error {
206		redisPodName := fmt.Sprintf("%s-redis", kvCache.Name)
207		redisServiceName := fmt.Sprintf("%s-redis", kvCache.Name)
208	
209		// Delete the Redis Pod (ignore NotFound — may not exist).
210		pod := &corev1.Pod{}
211		pod.Name = redisPodName
212		pod.Namespace = kvCache.Namespace
213		if err := r.Client.Delete(ctx, pod); err != nil && !apierrors.IsNotFound(err) {
214			return fmt.Errorf("failed to delete Redis Pod %s: %w", redisPodName, err)
215		} else if err == nil {
216			klog.Infof("Deleted orphaned in-cluster Redis Pod %s/%s", kvCache.Namespace, redisPodName)
217		}
218	
219		// Delete the Redis Service (ignore NotFound — may not exist).
220		svc := &corev1.Service{}
221		svc.Name = redisServiceName
222		svc.Namespace = kvCache.Namespace
223		if err := r.Client.Delete(ctx, svc); err != nil && !apierrors.IsNotFound(err) {
224			return fmt.Errorf("failed to delete Redis Service %s: %w", redisServiceName, err)
225		} else if err == nil {
226			klog.Infof("Deleted orphaned in-cluster Redis Service %s/%s", kvCache.Namespace, redisServiceName)
227		}
228	
229		return nil
230	}
