296				},
297				Template: corev1.PodTemplateSpec{
298					ObjectMeta: metav1.ObjectMeta{
299						Labels: map[string]string{
300							constants.KVCacheLabelKeyIdentifier: kvCache.Name,
301							constants.KVCacheLabelKeyRole:       constants.KVCacheLabelValueRoleCache,
302						},
303						Annotations: annotations,
304					},
305					Spec: corev1.PodSpec{
