314									{Name: "service", ContainerPort: int32(params.RdmaPort), Protocol: corev1.ProtocolTCP},
315									{Name: "manage", ContainerPort: int32(params.AdminPort), Protocol: corev1.ProtocolTCP},
316								},
317								Command: []string{
318									"infinistore",
319								},
320								Args:      kvCacheServerArgs,
321								Env:       envs,
322								Resources: kvCache.Spec.Cache.Resources,
323								SecurityContext: &corev1.SecurityContext{
324									// required to use RDMA
325									Capabilities: &corev1.Capabilities{
326										Add: []corev1.Capability{
327											"IPC_LOCK",
328											"SYS_RESOURCE", // infinistore only
329										},
330									},
331									// if IPC_LOCK doesn't work, then we can consider privileged
332									Privileged: &privileged,
333								},
334								VolumeMounts: []corev1.VolumeMount{
335									{
336										Name:      "shared-mem",
337										MountPath: "/dev/shm",
338									},
339								},
340							},
341						},
342						Volumes: []corev1.Volume{
343							{
344								Name: "shared-mem",
345								VolumeSource: corev1.VolumeSource{
346									EmptyDir: &corev1.EmptyDirVolumeSource{
347										Medium: corev1.StorageMediumMemory,
348									},
349								},
350							},
351						},
352					},
353				},
354			},
355		}
356		return ss
357	}
