359	func buildHeadlessServiceForInfiniStore(kvCache *orchestrationv1alpha1.KVCache) *corev1.Service {
360		params := getInfiniStoreParams(kvCache.GetAnnotations())
361		rdmaPort := int32(params.RdmaPort)
362		managePort := int32(params.AdminPort)
363		ports := kvCache.Spec.Service.Ports
