365			ports = []corev1.ServicePort{
366				{Name: "service", Port: rdmaPort, TargetPort: intstr.FromInt32(rdmaPort), Protocol: corev1.ProtocolTCP},
367				{Name: "manage", Port: managePort, TargetPort: intstr.FromInt32(managePort), Protocol: corev1.ProtocolTCP},
368			}
369		}
370	
371		service := &corev1.Service{
372			ObjectMeta: metav1.ObjectMeta{
373				Name:      fmt.Sprintf("%s-headless-service", kvCache.Name),
374				Namespace: kvCache.Namespace,
375				Labels: map[string]string{
376					constants.KVCacheLabelKeyIdentifier: kvCache.Name,
377				},
378				OwnerReferences: []metav1.OwnerReference{
379					*metav1.NewControllerRef(kvCache, orchestrationv1alpha1.GroupVersion.WithKind("KVCache")),
380				},
381			},
382			Spec: corev1.ServiceSpec{
383				Ports: ports,
384				Selector: map[string]string{
385					constants.KVCacheLabelKeyIdentifier: kvCache.Name,
386					constants.KVCacheLabelKeyRole:       constants.KVCacheLabelValueRoleCache,
387				},
388				Type:      kvCache.Spec.Service.Type,
389				ClusterIP: corev1.ClusterIPNone,
390			},
