395	func getInfiniStoreParams(annotations map[string]string) *InfiniStoreParams {
396		return &InfiniStoreParams{
397			LinkType:     utils.GetStringAnnotationOrDefault(annotations, KVCacheAnnotationLinkType, defaultInfinistoreLinkType),
398			HintGIDIndex: utils.GetPositiveIntAnnotationOrDefault(annotations, KVCacheAnnotationHintGidIndex, defaultInfinistoreHintGIDIndex),
399			// doesn't support specify the annotations yet
400			RdmaPort:         defaultInfinistoreRDMAPort,
401			AdminPort:        defaultInfinistoreAdminPort,
402			TotalSlots:       defaultInfinistoreTotalSlots,
403			VirtualNodeCount: defaultInfinistoreVirtualNodeCount,
404		}
405	}
406	
407	// getPreallocSizeFromResources infers the preallocated memory size (in GiB) from container memory limits.
408	// It multiplies the limit by 0.9 and floors the result. If the computed value is less than 1, it returns 1 GiB.
409	// If limits are not specified, it falls back to requests. If neither is specified, it defaults to 1 GiB.
410	func getPreallocSizeFromResources(resources corev1.ResourceRequirements) int {
411		memQty, ok := resources.Limits[corev1.ResourceMemory]
412		if !ok {
413			// fallback to requests if limits not set
414			memQty, ok = resources.Requests[corev1.ResourceMemory]
415			if !ok {
416				return 1 // default to 1 GiB if neither is set
417			}
418		}
419	
420		// Convert to GiB (1 GiB = 1024^3 bytes)
421		memBytes := memQty.Value()
422		memGiB := float64(memBytes) / float64(1<<30)
423	
424		// Multiply by 0.9 and round down
425		prealloc := int(math.Floor(memGiB * 0.9))
426		if prealloc < 1 {
427			return 1
428		}
429		return prealloc
430	}
