35	type VineyardReconciler struct {
36		*BaseReconciler
37	}
38	
39	func NewVineyardReconciler(c client.Client) *VineyardReconciler {
40		return &VineyardReconciler{&BaseReconciler{Client: c}}
41	}
42	
43	func (r VineyardReconciler) Reconcile(ctx context.Context, kvCache *orchestrationv1alpha1.KVCache) (reconcile.Result, error) {
44		// Handle metadata Pods like etcd or redis in future.
45		if kvCache.Spec.Metadata != nil {
46			err := r.reconcileMetadataService(ctx, kvCache)
47			if err != nil {
48				return ctrl.Result{}, err
49			}
50		}
51	
52		// Handle Vineyard kvCache Deployment
53		deployment := buildVineyardDeployment(kvCache)
54		if err := r.ReconcileDeploymentObject(ctx, deployment); err != nil {
55			return ctrl.Result{}, err
56		}
57	
58		// Handle Vineyard Services
59		service := buildVineyardRpcService(kvCache)
60		if err := r.ReconcileServiceObject(ctx, service); err != nil {
61			return ctrl.Result{}, err
62		}
63	
64		return ctrl.Result{}, nil
65	}
66	
67	func (r *VineyardReconciler) reconcileMetadataService(ctx context.Context, kvCache *orchestrationv1alpha1.KVCache) error {
68		if kvCache.Spec.Metadata.Etcd == nil && kvCache.Spec.Metadata.Redis == nil {
69			return errors.New("either etcd or redis configuration is required")
70		}
71	
72		if kvCache.Spec.Metadata.Etcd != nil {
73			return r.reconcileEtcdService(ctx, kvCache)
74		}
75	
76		return nil
77	}
78	
79	func (r *VineyardReconciler) reconcileEtcdService(ctx context.Context, kvCache *orchestrationv1alpha1.KVCache) error {
80		// We only support etcd at this moment, redis will be supported later.
81		replicas := int(kvCache.Spec.Metadata.Etcd.Runtime.Replicas)
82	
83		// Reconcile etcd pods and services based on the number of replicas specified
84		for i := 0; i < replicas; i++ {
85			etcdPodName := fmt.Sprintf("%s-etcd-%d", kvCache.Name, i)
86	
87			// Create or update the etcd pod
88			pod := buildEtcdPod(kvCache, etcdPodName)
89			if err := r.ReconcilePodObject(ctx, pod); err != nil {
90				return err
91			}
92	
93			// Create or update the etcd service for each pod
94			etcdService := buildEtcdPodService(etcdPodName, kvCache)
95			if err := r.ReconcileServiceObject(ctx, etcdService); err != nil {
96				return err
97			}
98		}
99	
100		// Reconcile the RPC service once for all etcd instances
101		etcdService := buildEtcdAggregateService(kvCache)
102	
103		if err := r.ReconcileServiceObject(ctx, etcdService); err != nil {
104			return err
105		}
106	
107		return nil
108	}
