110	func buildEtcdPod(kvCache *orchestrationv1alpha1.KVCache, etcdPodName string) *corev1.Pod {
111		image := kvCache.Spec.Cache.Image
112		if kvCache.Spec.Metadata.Etcd.Runtime.Image != "" {
113			image = kvCache.Spec.Metadata.Etcd.Runtime.Image
114		}
115	
116		pod := &corev1.Pod{
117			ObjectMeta: metav1.ObjectMeta{
118				Name:      etcdPodName,
119				Namespace: kvCache.Namespace,
120				Labels: map[string]string{
121					constants.KVCacheLabelKeyIdentifier:    kvCache.Name,
122					constants.KVCacheLabelKeyRole:          constants.KVCacheLabelValueRoleMetadata,
123					constants.KVCacheLabelKeyMetadataIndex: etcdPodName,
124				},
125				OwnerReferences: []metav1.OwnerReference{
126					*metav1.NewControllerRef(kvCache, orchestrationv1alpha1.GroupVersion.WithKind("KVCache")),
127				},
128			},
129			Spec: corev1.PodSpec{
130				Containers: []corev1.Container{
131					{
132						Name:  "etcd",
133						Image: image, // share the same kv cache image
134						Ports: []corev1.ContainerPort{
135							{Name: "client", ContainerPort: 2379, Protocol: corev1.ProtocolTCP},
136							{Name: "server", ContainerPort: 2380, Protocol: corev1.ProtocolTCP},
137						},
138						Command: []string{
139							"etcd",
140							"--name",
141							etcdPodName,
142							"--initial-advertise-peer-urls",
143							fmt.Sprintf("http://%s:2380", etcdPodName),
144							"--advertise-client-urls",
145							fmt.Sprintf("http://%s:2379", etcdPodName),
146							"--listen-peer-urls",
147							"http://0.0.0.0:2380",
148							"--listen-client-urls",
149							"http://0.0.0.0:2379",
150							"--initial-cluster",
151							fmt.Sprintf("%s=http://%s:2380", etcdPodName, etcdPodName),
152							"--initial-cluster-state",
153							"new",
154						},
155					},
156				},
157			},
158		}
159		return pod
160	}
