162	func buildEtcdPodService(etcdPodName string, kvCache *orchestrationv1alpha1.KVCache) *corev1.Service {
163		etcdService := &corev1.Service{
164			ObjectMeta: metav1.ObjectMeta{
165				Name:      etcdPodName,
166				Namespace: kvCache.Namespace,
167				Labels: map[string]string{
168					constants.KVCacheLabelKeyIdentifier:    kvCache.Name,
169					constants.KVCacheLabelKeyRole:          constants.KVCacheLabelValueRoleMetadata,
170					constants.KVCacheLabelKeyMetadataIndex: etcdPodName,
171				},
172				OwnerReferences: []metav1.OwnerReference{
173					*metav1.NewControllerRef(kvCache, orchestrationv1alpha1.GroupVersion.WithKind("KVCache")),
174				},
175			},
176			Spec: corev1.ServiceSpec{
177				Ports: []corev1.ServicePort{
178					{Name: "client", Port: 2379, TargetPort: intstr.FromInt32(2379), Protocol: corev1.ProtocolTCP},
179					{Name: "server", Port: 2380, TargetPort: intstr.FromInt32(2380), Protocol: corev1.ProtocolTCP},
180				},
181				Selector: map[string]string{
182					constants.KVCacheLabelKeyIdentifier:    kvCache.Name,
183					constants.KVCacheLabelKeyRole:          constants.KVCacheLabelValueRoleMetadata,
184					constants.KVCacheLabelKeyMetadataIndex: etcdPodName,
185				},
186				Type: corev1.ServiceTypeClusterIP,
187			},
188		}
189		return etcdService
190	}
