231		}
232	
233		affinity := corev1.Affinity{}
234	
235		if value, ok := kvCache.Annotations[constants.KVCacheAnnotationNodeAffinityGPUType]; ok {
236			matchKey := constants.KVCacheAnnotationNodeAffinityDefaultKey
237			if key, exist := kvCache.Annotations[constants.KVCacheAnnotationNodeAffinityKey]; exist {
