312					MatchLabels: map[string]string{
313						constants.KVCacheLabelKeyIdentifier: kvCache.Name,
314						constants.KVCacheLabelKeyRole:       constants.KVCacheLabelValueRoleCache,
315					},
316				},
317				Template: corev1.PodTemplateSpec{
318					ObjectMeta: metav1.ObjectMeta{
319						Labels: map[string]string{
320							constants.KVCacheLabelKeyIdentifier: kvCache.Name,
321							constants.KVCacheLabelKeyRole:       constants.KVCacheLabelValueRoleCache,
322						},
323					},
324					Spec: corev1.PodSpec{
