338								Resources:       kvCache.Spec.Cache.Resources,
339								ImagePullPolicy: corev1.PullPolicy(kvCache.Spec.Cache.ImagePullPolicy),
340								ReadinessProbe: &corev1.Probe{
341									ProbeHandler: corev1.ProbeHandler{
342										Exec: &corev1.ExecAction{
343											Command: []string{"ls", "/var/run/vineyard.sock"},
344										},
345									},
346								},
347								LivenessProbe: &corev1.Probe{
348									FailureThreshold: 3,
